import { PERFORMANCE_AND_BREAKDOWN_MOCK_ONLY } from '../../constants';

type WaterfallOptionTuple = { label: string; value: string };

type WaterfallScopeBlock = {
  values: WaterfallOptionTuple[];
  default: WaterfallOptionTuple;
};

export type PerformanceAndBreakdownWaterfallOptionsByScope = Record<
  string,
  WaterfallScopeBlock
>;

type SubFilterScopeBlock = {
  values?: Array<{ label: string; value: string }>;
  default?: { label: string; value: string };
};

type WaterfallOptionsSubFilterEntry = {
  values?: Record<string, SubFilterScopeBlock>;
  default?: SubFilterScopeBlock;
  enabled?: boolean;
};

export type PerformanceAndBreakdownWaterfallSubFiltersPayload = Record<
  string,
  WaterfallOptionsSubFilterEntry
>;

const WATERFALL_OPTIONS_KEY = 'innovation-hub-waterfall-options';

const t = (label: string, value: string): WaterfallOptionTuple => ({
  label,
  value,
});

const block = (
  values: WaterfallOptionTuple[],
  defaultTuple: WaterfallOptionTuple,
): WaterfallScopeBlock => ({ values, default: defaultTuple });

export const PERFORMANCE_AND_BREAKDOWN_WATERFALL_OPTIONS_BY_SCOPE: PerformanceAndBreakdownWaterfallOptionsByScope =
  {
    global: block(
      [t('Brand', 'brand'), t('Country', 'country')],
      t('Country', 'country'),
    ),
    country: block([t('Brand', 'brand')], t('Brand', 'brand')),
    brand: block([t('Sub-Brand', 'sub_brand')], t('Sub-Brand', 'sub_brand')),
    sub_brand: block([t('SKU', 'sku')], t('SKU', 'sku')),
    sku: block([t('SKU', 'sku')], t('SKU', 'sku')),
  };

function cloneScopeBlock(blockValue: SubFilterScopeBlock): SubFilterScopeBlock {
  return {
    values: blockValue.values?.map((row) => ({ ...row })),
    default: blockValue.default ? { ...blockValue.default } : undefined,
  };
}

function scopesNeedMerge(
  remoteScopes: Record<string, SubFilterScopeBlock> | undefined,
): boolean {
  const brandScope = remoteScopes?.brand;
  const hasSubBrandOption = brandScope?.values?.some(
    (option) => option.value === 'sub_brand',
  );

  return !hasSubBrandOption || !remoteScopes?.sub_brand || !remoteScopes?.sku;
}

export function mergePerformanceAndBreakdownWaterfallSubFilterData(
  payload: Record<string, unknown> | null | undefined,
): PerformanceAndBreakdownWaterfallSubFiltersPayload | null {
  if (
    !PERFORMANCE_AND_BREAKDOWN_MOCK_ONLY ||
    !payload?.[WATERFALL_OPTIONS_KEY]
  ) {
    return null;
  }

  const remoteEntry = payload[
    WATERFALL_OPTIONS_KEY
  ] as WaterfallOptionsSubFilterEntry;
  const remoteScopes = remoteEntry.values;

  if (!scopesNeedMerge(remoteScopes)) {
    return null;
  }

  const mergedScopes: Record<string, SubFilterScopeBlock> = {
    ...(remoteScopes
      ? Object.fromEntries(
          Object.entries(remoteScopes).map(([scope, scopeBlock]) => [
            scope,
            cloneScopeBlock(scopeBlock),
          ]),
        )
      : {}),
  };

  for (const [scope, localBlock] of Object.entries(
    PERFORMANCE_AND_BREAKDOWN_WATERFALL_OPTIONS_BY_SCOPE,
  )) {
    mergedScopes[scope] = cloneScopeBlock(localBlock);
  }

  return {
    ...payload,
    [WATERFALL_OPTIONS_KEY]: {
      ...remoteEntry,
      values: mergedScopes,
      default: cloneScopeBlock(
        mergedScopes.global ??
          PERFORMANCE_AND_BREAKDOWN_WATERFALL_OPTIONS_BY_SCOPE.global,
      ),
      enabled: remoteEntry.enabled ?? true,
    },
  };
}
